1	/**
2	 * WebMCP Manager
3	 * 管理动态网站工具的注册和执行
4	 */
5	
6	import { siteToolsConfig, matchSiteConfig, SiteConfig, SiteTool } from './site-tools-config';
7	import { getLocalRecordedSiteConfig, getLocalRecordedSiteSummaries } from './recorder';
8	import { NativeMessageType } from 'mcp-chrome-shared';
9	import { emit as emitBusMessage } from '@/entrypoints/background/native-message-bus';
10	
11	// Worldbook API 配置
12	const DEFAULT_WORLDBOOK_API_URL = 'https://worldbook.it.com/api/webmcp';
13	let cachedWorldbookApiUrl: string | null = null;
14	let cachedWorldbookEnabled: boolean | null = null;
15	
16	function getStorage<T extends Record<string, any>>(keys: string[]): Promise<T> {
17	  return new Promise((resolve) => {
18	    chrome.storage.local.get(keys, (result) => resolve(result as T));
19	  });
20	}
21	
22	async function isWorldbookWebMCPEnabled(): Promise<boolean> {
23	  if (cachedWorldbookEnabled !== null) {
24	    return cachedWorldbookEnabled;
25	  }
26	
27	  try {
28	    const result = await getStorage<{ worldbookWebMCPEnabled?: boolean }>([
29	      'worldbookWebMCPEnabled',
30	    ]);
31	    // Default to true
32	    cachedWorldbookEnabled = result.worldbookWebMCPEnabled !== false;
33	    return cachedWorldbookEnabled;
34	  } catch (error) {
35	    console.log('[WebMCP] Failed to read Worldbook WebMCP preference:', error);
36	    return true; // Enable by default
37	  }
38	}
39	
40	async function getWorldbookApiUrl(): Promise<string> {
41	  if (cachedWorldbookApiUrl) {
42	    return cachedWorldbookApiUrl;
43	  }
44	
45	  try {
46	    const result = await getStorage<{ webmcpApiUrl?: string; worldbookApiUrl?: string }>([
47	      'webmcpApiUrl',
48	      'worldbookApiUrl',
49	    ]);
50	    const candidate = (result.webmcpApiUrl || result.worldbookApiUrl || '').trim();
51	    if (candidate) {
52	      cachedWorldbookApiUrl = candidate;
53	      return cachedWorldbookApiUrl;
54	    }
55	  } catch (error) {
56	    console.log('[WebMCP] Failed to read Worldbook API override from storage:', error);
57	  }
58	
59	  cachedWorldbookApiUrl = DEFAULT_WORLDBOOK_API_URL;
60	  return cachedWorldbookApiUrl;
61	}
62	
63	chrome.storage.onChanged.addListener((changes, areaName) => {
64	  if (areaName !== 'local') return;
65	  if (changes.webmcpApiUrl || changes.worldbookApiUrl) {
66	    const next = (
67	      (changes.webmcpApiUrl?.newValue as string | undefined) ||
68	      (changes.worldbookApiUrl?.newValue as string | undefined) ||
69	      ''
70	    ).trim();
71	    cachedWorldbookApiUrl = next || DEFAULT_WORLDBOOK_API_URL;
72	  }
73	  if (changes.worldbookWebMCPEnabled !== undefined) {
74	    cachedWorldbookEnabled = changes.worldbookWebMCPEnabled.newValue !== false;
75	    console.log(`[WebMCP] Worldbook WebMCP preference changed to: ${cachedWorldbookEnabled}`);
76	  }
77	});
78	
79	// Debounce timeout for native server notification
80	let notifyNativeTimeout: ReturnType<typeof setTimeout> | null = null;
81	
82	/**
83	 * Send WebMCP tools update to native server
84	 */
85	function notifyNativeServerToolsUpdate(
86	  action: 'register' | 'unregister',
87	  tabId: number,
88	  siteName?: string,
89	  tools?: SiteTool[],
90	) {
91	  // Debounce to prevent rapid fire
92	  if (notifyNativeTimeout) {
93	    clearTimeout(notifyNativeTimeout);
94	  }
95	
96	  notifyNativeTimeout = setTimeout(() => {
97	    const payload: any = { action, tabId };
98	
99	    if (action === 'register' && siteName && tools) {
100	      payload.siteName = siteName;
101	      // 使用 WebMCP 标准格式：inputSchema
102	      payload.tools = tools.map((t) => ({
103	        name: t.name,
104	        description: t.description,
105	        inputSchema: t.inputSchema,
106	      }));
107	    }
108	
109	    // Send message via internal message bus (for intra-background communication)
110	    emitBusMessage('forward_to_native', {
111	      type: NativeMessageType.WEBMCP_TOOLS_UPDATE,
112	      payload,
113	    });
114	    console.log(`[WebMCP] Sent tools update to native server: ${action}`);
115	  }, 300);
116	}
117	
118	// API 响应类型 - WebMCP 标准格式
119	interface ApiInputSchema {
120	  type: 'object';
121	  properties: Record<
122	    string,
123	    {
124	      type: string;
125	      description?: string;
126	      enum?: string[];
127	    }
128	  >;
129	  required?: string[];
130	}
131	
132	interface ApiTool {
133	  name: string;
134	  description: string;
135	  inputSchema: ApiInputSchema;
136	  handler: string;
137	}
138	
139	interface ApiSiteConfig {
140	  url_pattern: string;
141	  site_name: string;
142	  tools: ApiTool[];
143	}
144	
145	// 存储当前已注册的网站工具
146	const registeredSiteTools = new Map<number, SiteConfig>();
147	
148	function mergeSiteConfigs(
149	  primary: SiteConfig | null,
150	  secondary: SiteConfig | null,
151	): SiteConfig | null {
152	  if (!primary && !secondary) return null;
153	  if (!primary) return secondary;
154	  if (!secondary) return primary;
155	
156	  const mergedTools: SiteTool[] = [];
157	  const seen = new Set<string>();
158	  for (const tool of [...primary.tools, ...secondary.tools]) {
159	    if (seen.has(tool.name)) continue;
160	    seen.add(tool.name);
161	    mergedTools.push(tool);
162	  }
163	
164	  return {
165	    ...primary,
166	    tools: mergedTools,
167	  };
168	}
169	
170	/**
171	 * 将 API 响应转换为本地 SiteConfig 格式
172	 */
173	function convertApiConfig(apiConfig: ApiSiteConfig): SiteConfig {
174	  return {
175	    urlPattern: new RegExp(apiConfig.url_pattern),
176	    siteName: apiConfig.site_name,
177	    tools: apiConfig.tools.map((t) => ({
178	      name: t.name,
179	      description: t.description,
180	      inputSchema: t.inputSchema,
181	      handler: t.handler,
182	    })),
183	  };
184	}
185	
186	/**
187	 * 从 Worldbook API 获取匹配的站点配置
188	 */
189	async function fetchSiteConfigFromAPI(url: string): Promise<SiteConfig | null> {
190	  try {
191	    const apiUrl = await getWorldbookApiUrl();
192	    const response = await fetch(`${apiUrl}/match?url=${encodeURIComponent(url)}`);
193	    if (!response.ok) {
194	      console.log(`[WebMCP] API request failed: ${response.status}`);
195	      return null;
196	    }
197	    const data = await response.json();
198	    if (!data) return null;
199	    return convertApiConfig(data as ApiSiteConfig);
200	  } catch (error) {
201	    console.log(`[WebMCP] Failed to fetch from API, falling back to local config:`, error);
202	    return null;
203	  }
204	}
205	
206	/**
207	 * Get site config - prefer API, fallback to local config
208	 */
209	async function getSiteConfig(url: string): Promise<SiteConfig | null> {
210	  const recordedConfig = await getLocalRecordedSiteConfig(url);
211	
212	  // Check if Worldbook WebMCP is enabled
213	  const worldbookEnabled = await isWorldbookWebMCPEnabled();
214	
215	  if (worldbookEnabled) {
216	    // Try to fetch from Worldbook API first
217	    const apiConfig = await fetchSiteConfigFromAPI(url);
218	    if (apiConfig) {
219	      console.log(`[WebMCP] Got config from Worldbook API: ${apiConfig.siteName}`);
220	      return mergeSiteConfigs(apiConfig, recordedConfig);
221	    }
222	  } else {
223	    console.log(`[WebMCP] Worldbook WebMCP disabled, skipping API request`);
224	  }
225	
226	  // Fallback to local config if API fails or disabled
227	  const localConfig = matchSiteConfig(url);
228	  if (localConfig) {
229	    console.log(`[WebMCP] Using local config: ${localConfig.siteName}`);
230	  }
231	  return mergeSiteConfigs(localConfig, recordedConfig);
232	}
233	
234	/**
235	 * 初始化 WebMCP 监听器
236	 */
237	export function initWebMCPListener() {
238	  // 监听标签页更新，自动检测并注册工具
239	  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
240	    if (changeInfo.status === 'complete' && tab.url) {
241	      // Check if we need to unregister old tools (URL changed to non-matching site)
242	      const oldConfig = registeredSiteTools.get(tabId);
243	
244	      const siteConfig = await getSiteConfig(tab.url);
245	      if (siteConfig) {
246	        // Only register if not already registered for this site
247	        if (!oldConfig || oldConfig.siteName !== siteConfig.siteName) {
248	          console.log(`[WebMCP] 检测到匹配的网站: ${siteConfig.siteName} (${tab.url})`);
249	          await registerSiteTools(tabId, siteConfig);
250	
251	          // Notify native server about new tools
252	          notifyNativeServerToolsUpdate('register', tabId, siteConfig.siteName, siteConfig.tools);
253	        }
254	      } else if (oldConfig) {
255	        // URL changed to non-matching site, unregister old tools
256	        console.log(`[WebMCP] 标签页 ${tabId} 导航离开 ${oldConfig.siteName}，清理工具`);
257	        registeredSiteTools.delete(tabId);
258	        notifyNativeServerToolsUpdate('unregister', tabId);
259	      }
260	    }
261	  });
262	
263	  // 监听标签页关闭，清理工具
264	  chrome.tabs.onRemoved.addListener((tabId) => {
265	    if (registeredSiteTools.has(tabId)) {
266	      console.log(`[WebMCP] 标签页 ${tabId} 关闭，清理工具`);
267	      registeredSiteTools.delete(tabId);
268	      notifyNativeServerToolsUpdate('unregister', tabId);
269	    }
270	  });
271	
272	  // 监听消息请求（用于调试和测试）
273	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
274	    if (request.type === 'webmcp:detect-tools') {
275	      detectAndRegisterTools()
276	        .then((result) => sendResponse({ success: true, result }))
277	        .catch((error) => sendResponse({ success: false, error: error.message }));
278	      return true; // 保持端口打开用于异步响应
279	    }
280	    if (request.type === 'webmcp:call-tool') {
281	      const { tabId, toolName, params } = request;
282	      executeWebMCPTool(tabId, toolName, params || {})
283	        .then((result) => sendResponse({ success: true, ...result }))
284	        .catch((error) => sendResponse({ success: false, error: error.message }));
285	      return true;
286	    }
287	    if (request.type === 'webmcp:list-tools') {
288	      const allTools = getAllRegisteredTools();
289	      const result: any[] = [];
290	      allTools.forEach((config, tid) => {
291	        result.push({
292	          tabId: tid,
293	          siteName: config.siteName,
294	          tools: config.tools.map((t) => t.name),
295	        });
296	      });
297	      sendResponse({ success: true, registeredTools: result });
298	      return true;
299	    }
300	  });
301	
302	  console.log('[WebMCP] Manager initialized');
303	}
304	
305	/**
306	 * 为标签页注册网站工具
307	 */
308	async function registerSiteTools(tabId: number, siteConfig: SiteConfig) {
309	  try {
310	    // 注入 WebMCP 执行脚本
311	    await chrome.scripting.executeScript({
312	      target: { tabId },
313	      func: injectWebMCPExecutor,
314	      args: [siteConfig.tools.map((t) => ({ name: t.name, handler: t.handler }))],
315	      world: 'MAIN',
316	    });
317	
318	    // 注入桥接脚本用于通信
319	    await chrome.scripting.executeScript({
320	      target: { tabId },
321	      func: injectWebMCPBridge,
322	      world: 'ISOLATED',
323	    });
324	
325	    registeredSiteTools.set(tabId, siteConfig);
326	    console.log(`[WebMCP] 已为标签页 ${tabId} 注册 ${siteConfig.tools.length} 个工具`);
327	  } catch (error) {
328	    console.error(`[WebMCP] 注册工具失败:`, error);
329	  }
330	}
331	
332	/**
333	 * 注入到 MAIN world 的执行器
334	 * 使用 lazy eval + 缓存：只存储 handler 字符串，首次调用时编译并缓存
335	 * 这样既安全（避免 IIFE 在页面加载时执行），又高效（后续调用复用编译结果）
336	 */
337	function injectWebMCPExecutor(tools: Array<{ name: string; handler: string }>) {
338	  // 防止重复注入
339	  if ((window as any).__WEBMCP_EXECUTOR_LOADED__) return;
340	  (window as any).__WEBMCP_EXECUTOR_LOADED__ = true;
341	
342	  // 存储工具 handler 字符串（不立即 eval）
343	  const toolHandlers = new Map<string, string>();
344	  // 缓存编译后的函数
345	  const compiledCache = new Map<string, (...args: unknown[]) => unknown>();
346	
347	  // 只存储 handler 字符串，不编译
348	  tools.forEach((tool) => {
349	    toolHandlers.set(tool.name, tool.handler);
350	    console.log(`[WebMCP] 注册工具: ${tool.name}`);
351	  });
352	
353	  // 监听工具执行请求 (通过 postMessage 从 ISOLATED world)
354	  // 注意：不能使用 async/await，因为 esbuild 会转换成 __async helper，在 MAIN world 中不存在
355	  window.addEventListener('message', (event) => {
356	    if (event.source !== window || event.data?.type !== 'webmcp:execute-tool') return;
357	
358	    const { requestId, toolName, params } = event.data;
359	    console.log(`[WebMCP] 执行工具: ${toolName}`, params);
360	
361	    const handlerCode = toolHandlers.get(toolName);
362	    if (!handlerCode) {
363	      window.postMessage(
364	        {
365	          type: 'webmcp:tool-result',
366	          requestId,
367	          result: null,
368	          error: `工具 ${toolName} 未找到`,
369	        },
370	        '*',
371	      );
372	      return;
373	    }
374	
375	    // Lazy eval + 缓存: 首次调用时编译，后续复用
376	    Promise.resolve()
377	      .then(() => {
378	        let handler = compiledCache.get(toolName);
379	        if (!handler) {
380	          console.log(`[WebMCP] 首次编译工具: ${toolName}`);
381	          handler = eval(`(${handlerCode})`) as (...args: unknown[]) => unknown;
382	          compiledCache.set(toolName, handler);
383	        }
384	        return handler(params);
385	      })
386	      .then((result) => {
387	        window.postMessage(
388	          {
389	            type: 'webmcp:tool-result',
390	            requestId,
391	            result,
392	            error: null,
393	          },
394	          '*',
395	        );
396	      })
397	      .catch((error) => {
398	        window.postMessage(
399	          {
400	            type: 'webmcp:tool-result',
401	            requestId,
402	            result: null,
403	            error: error.message || String(error),
404	          },
405	          '*',
406	        );
407	      });
408	  });
409	
410	  console.log('[WebMCP] Executor initialized with', toolHandlers.size, 'tools');
411	}
412	
413	/**
414	 * 注入到 ISOLATED world 的桥接脚本
415	 */
416	function injectWebMCPBridge() {
417	  if ((window as any).__WEBMCP_BRIDGE_LOADED__) return;
418	  (window as any).__WEBMCP_BRIDGE_LOADED__ = true;
419	
420	  const pendingRequests = new Map<string, (response: any) => void>();
421	
422	  // 监听来自 background 的消息
423	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
424	    if (request.type === 'webmcp:call-tool') {
425	      const requestId = `req-${Date.now()}-${Math.random()}`;
426	      pendingRequests.set(requestId, sendResponse);
427	
428	      // 通过 postMessage 转发到 MAIN world
429	      window.postMessage(
430	        {
431	          type: 'webmcp:execute-tool',
432	          requestId,
433	          toolName: request.toolName,
434	          params: request.params,
435	        },
436	        '*',
437	      );
438	
439	      return true; // 异步响应
440	    }
441	  });
442	
443	  // 监听来自 MAIN world 的结果 (通过 postMessage)
444	  window.addEventListener('message', (event) => {
445	    if (event.source !== window || event.data?.type !== 'webmcp:tool-result') return;
446	
447	    const { requestId, result, error } = event.data;
448	    const sendResponse = pendingRequests.get(requestId);
449	    if (sendResponse) {
450	      sendResponse({ result, error });
451	      pendingRequests.delete(requestId);
452	    }
453	  });
454	
455	  console.log('[WebMCP] Bridge initialized');
456	}
457	
458	/**
459	 * 获取指定标签页的可用工具
460	 */
461	export function getTabTools(tabId: number): SiteTool[] {
462	  const config = registeredSiteTools.get(tabId);
463	  return config?.tools || [];
464	}
465	
466	/**
467	 * 获取所有已注册的网站工具
468	 */
469	export function getAllRegisteredTools(): Map<number, SiteConfig> {
470	  return registeredSiteTools;
471	}
472	
473	/**
474	 * 等待标签页加载完成
475	 */
476	function waitForTabLoad(tabId: number, timeout = 15000): Promise<void> {
477	  return new Promise((resolve, reject) => {
478	    const timer = setTimeout(() => {
479	      chrome.tabs.onUpdated.removeListener(listener);
480	      reject(new Error('页面加载超时'));
481	    }, timeout);
482	
483	    const listener = (updatedTabId: number, changeInfo: chrome.tabs.TabChangeInfo) => {
484	      if (updatedTabId === tabId && changeInfo.status === 'complete') {
485	        clearTimeout(timer);
486	        chrome.tabs.onUpdated.removeListener(listener);
487	        // 额外等待一点时间让 JS 执行完成
488	        setTimeout(resolve, 500);
489	      }
490	    };
491	
492	    chrome.tabs.onUpdated.addListener(listener);
493	  });
494	}
495	
496	/**
497	 * 执行网站工具 - 直接在页面上执行
498	 * 支持 __navigate__ + __then__ 协议用于需要页面跳转的操作
499	 */
500	export async function executeWebMCPTool(
501	  tabId: number,
502	  toolName: string,
503	  params: Record<string, any>,
504	): Promise<{ result: any; error: string | null }> {
505	  const config = registeredSiteTools.get(tabId);
506	  if (!config) {
507	    return { result: null, error: '该标签页没有注册工具' };
508	  }
509	
510	  const tool = config.tools.find((t) => t.name === toolName);
511	  if (!tool) {
512	    return { result: null, error: `工具 ${toolName} 未找到` };
513	  }
514	
515	  try {
516	    // 直接在页面上执行工具 handler
517	    const results = await chrome.scripting.executeScript({
518	      target: { tabId },
519	      world: 'MAIN',
520	      func: (handlerCode: string, toolParams: Record<string, any>) => {
521	        return new Promise((resolve) => {
522	          try {
523	            // Defensive: if params is a string, parse it
524	            const actualParams =
525	              typeof toolParams === 'string' ? JSON.parse(toolParams) : toolParams;
526	
527	            const handler = eval(`(${handlerCode})`);
528	            Promise.resolve(handler(actualParams))
529	              .then((result) => resolve({ result, error: null }))
530	              .catch((err) => resolve({ result: null, error: err.message }));
531	          } catch (e: any) {
532	            resolve({ result: null, error: e.message });
533	          }
534	        });
535	      },
536	      args: [tool.handler, params],
537	    });
538	
539	    if (!results || !results[0]) {
540	      return { result: null, error: '执行失败' };
541	    }
542	
543	    const firstResult = results[0].result as { result: any; error: string | null };
544	
545	    // 检查是否需要导航 + 后续执行
546	    if (firstResult.result && firstResult.result.__navigate__ && firstResult.result.__then__) {
547	      const navigateUrl = firstResult.result.__navigate__;
548	      const thenCode = firstResult.result.__then__;
549	
550	      console.log(`[WebMCP] 导航到: ${navigateUrl}`);
551	
552	      // 导航到目标 URL
553	      await chrome.tabs.update(tabId, { url: navigateUrl });
554	
555	      // 等待页面加载完成
556	      await waitForTabLoad(tabId);
557	
558	      console.log(`[WebMCP] 页面加载完成，执行后续代码`);
559	
560	      // 重新注册工具到新页面
561	      const newTab = await chrome.tabs.get(tabId);
562	      if (newTab.url) {
563	        const newConfig = await getSiteConfig(newTab.url);
564	        if (newConfig) {
565	          await registerSiteTools(tabId, newConfig);
566	        }
567	      }
568	
569	      // 执行后续代码
570	      const thenResults = await chrome.scripting.executeScript({
571	        target: { tabId },
572	        world: 'MAIN',
573	        func: (code: string) => {
574	          return new Promise((resolve) => {
575	            try {
576	              const result = eval(code);
577	              Promise.resolve(result)
578	                .then((r) => resolve({ result: r, error: null }))
579	                .catch((err) => resolve({ result: null, error: err.message }));
580	            } catch (e: any) {
581	              resolve({ result: null, error: e.message });
582	            }
583	          });
584	        },
585	        args: [thenCode],
586	      });
587	
588	      if (thenResults && thenResults[0]) {
589	        return thenResults[0].result as { result: any; error: string | null };
590	      }
591	      return { result: null, error: '后续执行失败' };
592	    }
593	
594	    return firstResult;
595	  } catch (error: any) {
596	    return { result: null, error: error.message };
597	  }
598	}
599	
600	/**
601	 * 手动为指定标签页或当前活动标签页检测并注册工具
602	 * @param targetTabId - 可选，指定要检测的标签页 ID
603	 */
604	export async function detectAndRegisterTools(targetTabId?: number): Promise<{
605	  tabId: number;
606	  siteName: string;
607	  tools: string[];
608	} | null> {
609	  let tab: chrome.tabs.Tab | undefined;
610	
611	  if (targetTabId) {
612	    // 使用指定的 tabId
613	    tab = await chrome.tabs.get(targetTabId);
614	  } else {
615	    // 使用当前活动标签页
616	    const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
617	    tab = activeTab;
618	  }
619	
620	  if (!tab?.id || !tab.url) return null;
621	
622	  const siteConfig = await getSiteConfig(tab.url);
623	  if (!siteConfig) {
624	    if (registeredSiteTools.has(tab.id)) {
625	      registeredSiteTools.delete(tab.id);
626	      notifyNativeServerToolsUpdate('unregister', tab.id);
627	    }
628	    return null;
629	  }
630	
631	  await registerSiteTools(tab.id, siteConfig);
632	
633	  // Notify native server about the registered tools
634	  notifyNativeServerToolsUpdate('register', tab.id, siteConfig.siteName, siteConfig.tools);
635	
636	  return {
637	    tabId: tab.id,
638	    siteName: siteConfig.siteName,
639	    tools: siteConfig.tools.map((t) => t.name),
640	  };
641	}
642	
643	/**
644	 * Re-send all registered tools to native server
645	 * Called when native server restarts
646	 */
647	export function resendAllToolsToNative(): void {
648	  console.log('[WebMCP] Resending all registered tools to native server');
649	  registeredSiteTools.forEach((config, tabId) => {
650	    console.log(`[WebMCP] Resending tools for tab ${tabId}: ${config.siteName}`);
651	    notifyNativeServerToolsUpdate('register', tabId, config.siteName, config.tools);
652	  });
653	}
654	
655	/**
656	 * 获取所有配置的站点列表 (从 API)
657	 */
658	export async function getConfiguredSites(): Promise<
659	  Array<{
660	    site_name: string;
661	    url_pattern: string;
662	    tool_count: number;
663	    tools: string[];
664	  }>
665	> {
666	  // 检查 Worldbook WebMCP 是否启用
667	  const worldbookEnabled = await isWorldbookWebMCPEnabled();
668	
669	  if (worldbookEnabled) {
670	    try {
671	      const apiUrl = await getWorldbookApiUrl();
672	      const response = await fetch(`${apiUrl}/sites`);
673	      if (response.ok) {
674	        return await response.json();
675	      }
676	    } catch (error) {
677	      console.log('[WebMCP] Failed to fetch sites from API:', error);
678	    }
679	  }
680	
681	  // 返回本地配置作为后备
682	  const configuredSites = siteToolsConfig.map((c) => ({
683	    site_name: c.siteName,
684	    url_pattern: String(c.urlPattern),
685	    tool_count: c.tools.length,
686	    tools: c.tools.map((t) => t.name),
687	  }));
688	
689	  const recordedSites = await getLocalRecordedSiteSummaries();
690	  return [...configuredSites, ...recordedSites];
691	}
