1	/**
2	 * WebMCP Manager
3	 * 管理动态网站工具的注册和执行
4	 */
5	
6	import { siteToolsConfig, matchSiteConfig, SiteConfig, SiteTool } from './site-tools-config';
7	import { getLocalRecordedSiteConfig, getLocalRecordedSiteSummaries } from './recorder';
8	import { NativeMessageType } from 'mcp-chrome-shared';
9	import { emit as emitBusMessage } from '@/entrypoints/background/native-message-bus';
10	
11	// Worldbook API 配置
12	const DEFAULT_WORLDBOOK_API_URL = 'https://worldbook.it.com/api/webmcp';
13	let cachedWorldbookApiUrl: string | null = null;
14	let cachedWorldbookEnabled: boolean | null = null;
15	let cachedClientId: string | null = null;
16	
17	/**
18	 * 获取或生成用于分析追踪的匿名 clientId (UUID)
19	 * 用于统计 DAU/MAU，不关联任何个人身份信息
20	 */
21	async function getOrCreateClientId(): Promise<string> {
22	  if (cachedClientId) {
23	    return cachedClientId;
24	  }
25	
26	  try {
27	    const result = await getStorage<{ clientId?: string }>(['clientId']);
28	    if (result.clientId) {
29	      cachedClientId = result.clientId;
30	      return cachedClientId;
31	    }
32	
33	    // 生成新的 UUID
34	    cachedClientId = crypto.randomUUID();
35	    await chrome.storage.local.set({ clientId: cachedClientId });
36	    console.log('[WebMCP] Generated new anonymous clientId for analytics');
37	    return cachedClientId;
38	  } catch (error) {
39	    console.log('[WebMCP] Failed to get/create clientId:', error);
40	    // 降级：使用临时 ID，不持久化
41	    cachedClientId = crypto.randomUUID();
42	    return cachedClientId;
43	  }
44	}
45	
46	function getStorage<T extends Record<string, any>>(keys: string[]): Promise<T> {
47	  return new Promise((resolve) => {
48	    chrome.storage.local.get(keys, (result) => resolve(result as T));
49	  });
50	}
51	
52	async function isWorldbookWebMCPEnabled(): Promise<boolean> {
53	  if (cachedWorldbookEnabled !== null) {
54	    return cachedWorldbookEnabled;
55	  }
56	
57	  try {
58	    const result = await getStorage<{ worldbookWebMCPEnabled?: boolean }>([
59	      'worldbookWebMCPEnabled',
60	    ]);
61	    // Default to true
62	    cachedWorldbookEnabled = result.worldbookWebMCPEnabled !== false;
63	    return cachedWorldbookEnabled;
64	  } catch (error) {
65	    console.log('[WebMCP] Failed to read Worldbook WebMCP preference:', error);
66	    return true; // Enable by default
67	  }
68	}
69	
70	async function getWorldbookApiUrl(): Promise<string> {
71	  if (cachedWorldbookApiUrl) {
72	    return cachedWorldbookApiUrl;
73	  }
74	
75	  try {
76	    const result = await getStorage<{ webmcpApiUrl?: string; worldbookApiUrl?: string }>([
77	      'webmcpApiUrl',
78	      'worldbookApiUrl',
79	    ]);
80	    const candidate = (result.webmcpApiUrl || result.worldbookApiUrl || '').trim();
81	    if (candidate) {
82	      cachedWorldbookApiUrl = candidate;
83	      return cachedWorldbookApiUrl;
84	    }
85	  } catch (error) {
86	    console.log('[WebMCP] Failed to read Worldbook API override from storage:', error);
87	  }
88	
89	  cachedWorldbookApiUrl = DEFAULT_WORLDBOOK_API_URL;
90	  return cachedWorldbookApiUrl;
91	}
92	
93	chrome.storage.onChanged.addListener((changes, areaName) => {
94	  if (areaName !== 'local') return;
95	  if (changes.webmcpApiUrl || changes.worldbookApiUrl) {
96	    const next = (
97	      (changes.webmcpApiUrl?.newValue as string | undefined) ||
98	      (changes.worldbookApiUrl?.newValue as string | undefined) ||
99	      ''
100	    ).trim();
101	    cachedWorldbookApiUrl = next || DEFAULT_WORLDBOOK_API_URL;
102	  }
103	  if (changes.worldbookWebMCPEnabled !== undefined) {
104	    cachedWorldbookEnabled = changes.worldbookWebMCPEnabled.newValue !== false;
105	    console.log(`[WebMCP] Worldbook WebMCP preference changed to: ${cachedWorldbookEnabled}`);
106	  }
107	});
108	
109	// Debounce timeout for native server notification
110	let notifyNativeTimeout: ReturnType<typeof setTimeout> | null = null;
111	
112	/**
113	 * Send WebMCP tools update to native server
114	 */
115	function notifyNativeServerToolsUpdate(
116	  action: 'register' | 'unregister',
117	  tabId: number,
118	  siteName?: string,
119	  tools?: SiteTool[],
120	) {
121	  // Debounce to prevent rapid fire
122	  if (notifyNativeTimeout) {
123	    clearTimeout(notifyNativeTimeout);
124	  }
125	
126	  notifyNativeTimeout = setTimeout(() => {
127	    const payload: any = { action, tabId };
128	
129	    if (action === 'register' && siteName && tools) {
130	      payload.siteName = siteName;
131	      // 使用 WebMCP 标准格式：inputSchema
132	      payload.tools = tools.map((t) => ({
133	        name: t.name,
134	        description: t.description,
135	        inputSchema: t.inputSchema,
136	      }));
137	    }
138	
139	    // Send message via internal message bus (for intra-background communication)
140	    emitBusMessage('forward_to_native', {
141	      type: NativeMessageType.WEBMCP_TOOLS_UPDATE,
142	      payload,
143	    });
144	    console.log(`[WebMCP] Sent tools update to native server: ${action}`);
145	  }, 300);
146	}
147	
148	// API 响应类型 - WebMCP 标准格式
149	interface ApiInputSchema {
150	  type: 'object';
151	  properties: Record<
152	    string,
153	    {
154	      type: string;
155	      description?: string;
156	      enum?: string[];
157	    }
158	  >;
159	  required?: string[];
160	}
161	
162	interface ApiTool {
163	  name: string;
164	  description: string;
165	  inputSchema: ApiInputSchema;
166	  handler: string;
167	}
168	
169	interface ApiSiteConfig {
170	  url_pattern: string;
171	  site_name: string;
172	  tools: ApiTool[];
173	}
174	
175	// 存储当前已注册的网站工具
176	const registeredSiteTools = new Map<number, SiteConfig>();
177	
178	function mergeSiteConfigs(
179	  primary: SiteConfig | null,
180	  secondary: SiteConfig | null,
181	): SiteConfig | null {
182	  if (!primary && !secondary) return null;
183	  if (!primary) return secondary;
184	  if (!secondary) return primary;
185	
186	  const mergedTools: SiteTool[] = [];
187	  const seen = new Set<string>();
188	  for (const tool of [...primary.tools, ...secondary.tools]) {
189	    if (seen.has(tool.name)) continue;
190	    seen.add(tool.name);
191	    mergedTools.push(tool);
192	  }
193	
194	  return {
195	    ...primary,
196	    tools: mergedTools,
197	  };
198	}
199	
200	/**
201	 * 将 API 响应转换为本地 SiteConfig 格式
202	 */
203	function convertApiConfig(apiConfig: ApiSiteConfig): SiteConfig {
204	  return {
205	    urlPattern: new RegExp(apiConfig.url_pattern),
206	    siteName: apiConfig.site_name,
207	    tools: apiConfig.tools.map((t) => ({
208	      name: t.name,
209	      description: t.description,
210	      inputSchema: t.inputSchema,
211	      handler: t.handler,
212	    })),
213	  };
214	}
215	
216	/**
217	 * 从 Worldbook API 获取匹配的站点配置
218	 * 请求时带上匿名 clientId 用于 DAU/MAU 统计
219	 */
220	async function fetchSiteConfigFromAPI(url: string): Promise<SiteConfig | null> {
221	  try {
222	    const apiUrl = await getWorldbookApiUrl();
223	    const clientId = await getOrCreateClientId();
224	    const response = await fetch(`${apiUrl}/match?url=${encodeURIComponent(url)}`, {
225	      headers: {
226	        'X-Client-Id': clientId,
227	      },
228	    });
229	    if (!response.ok) {
230	      console.log(`[WebMCP] API request failed: ${response.status}`);
231	      return null;
232	    }
233	    const data = await response.json();
234	    if (!data) return null;
235	    return convertApiConfig(data as ApiSiteConfig);
236	  } catch (error) {
237	    console.log(`[WebMCP] Failed to fetch from API, falling back to local config:`, error);
238	    return null;
239	  }
240	}
241	
242	/**
243	 * Get site config - prefer API, fallback to local config
244	 */
245	async function getSiteConfig(url: string): Promise<SiteConfig | null> {
246	  const recordedConfig = await getLocalRecordedSiteConfig(url);
247	
248	  // Check if Worldbook WebMCP is enabled
249	  const worldbookEnabled = await isWorldbookWebMCPEnabled();
250	
251	  if (worldbookEnabled) {
252	    // Try to fetch from Worldbook API first
253	    const apiConfig = await fetchSiteConfigFromAPI(url);
254	    if (apiConfig) {
255	      console.log(`[WebMCP] Got config from Worldbook API: ${apiConfig.siteName}`);
256	      return mergeSiteConfigs(apiConfig, recordedConfig);
257	    }
258	  } else {
259	    console.log(`[WebMCP] Worldbook WebMCP disabled, skipping API request`);
260	  }
261	
262	  // Fallback to local config if API fails or disabled
263	  const localConfig = matchSiteConfig(url);
264	  if (localConfig) {
265	    console.log(`[WebMCP] Using local config: ${localConfig.siteName}`);
266	  }
267	  return mergeSiteConfigs(localConfig, recordedConfig);
268	}
269	
270	/**
271	 * 初始化 WebMCP 监听器
272	 */
273	export function initWebMCPListener() {
274	  // 监听标签页更新，自动检测并注册工具
275	  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
276	    if (changeInfo.status === 'complete' && tab.url) {
277	      // Check if we need to unregister old tools (URL changed to non-matching site)
278	      const oldConfig = registeredSiteTools.get(tabId);
279	
280	      const siteConfig = await getSiteConfig(tab.url);
281	      if (siteConfig) {
282	        // Only register if not already registered for this site
283	        if (!oldConfig || oldConfig.siteName !== siteConfig.siteName) {
284	          console.log(`[WebMCP] 检测到匹配的网站: ${siteConfig.siteName} (${tab.url})`);
285	          await registerSiteTools(tabId, siteConfig);
286	
287	          // Notify native server about new tools
288	          notifyNativeServerToolsUpdate('register', tabId, siteConfig.siteName, siteConfig.tools);
289	        }
290	      } else if (oldConfig) {
291	        // URL changed to non-matching site, unregister old tools
292	        console.log(`[WebMCP] 标签页 ${tabId} 导航离开 ${oldConfig.siteName}，清理工具`);
293	        registeredSiteTools.delete(tabId);
294	        notifyNativeServerToolsUpdate('unregister', tabId);
295	      }
296	    }
297	  });
298	
299	  // 监听标签页关闭，清理工具
300	  chrome.tabs.onRemoved.addListener((tabId) => {
301	    if (registeredSiteTools.has(tabId)) {
302	      console.log(`[WebMCP] 标签页 ${tabId} 关闭，清理工具`);
303	      registeredSiteTools.delete(tabId);
304	      notifyNativeServerToolsUpdate('unregister', tabId);
305	    }
306	  });
307	
308	  // 监听消息请求（用于调试和测试）
309	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
310	    if (request.type === 'webmcp:detect-tools') {
311	      detectAndRegisterTools()
312	        .then((result) => sendResponse({ success: true, result }))
313	        .catch((error) => sendResponse({ success: false, error: error.message }));
314	      return true; // 保持端口打开用于异步响应
315	    }
316	    if (request.type === 'webmcp:call-tool') {
317	      const { tabId, toolName, params } = request;
318	      executeWebMCPTool(tabId, toolName, params || {})
319	        .then((result) => sendResponse({ success: true, ...result }))
320	        .catch((error) => sendResponse({ success: false, error: error.message }));
321	      return true;
322	    }
323	    if (request.type === 'webmcp:list-tools') {
324	      const allTools = getAllRegisteredTools();
325	      const result: any[] = [];
326	      allTools.forEach((config, tid) => {
327	        result.push({
328	          tabId: tid,
329	          siteName: config.siteName,
330	          tools: config.tools.map((t) => t.name),
331	        });
332	      });
333	      sendResponse({ success: true, registeredTools: result });
334	      return true;
335	    }
336	  });
337	
338	  console.log('[WebMCP] Manager initialized');
339	}
340	
341	/**
342	 * 为标签页注册网站工具
343	 */
344	async function registerSiteTools(tabId: number, siteConfig: SiteConfig) {
345	  try {
346	    // 注入 WebMCP 执行脚本
347	    await chrome.scripting.executeScript({
348	      target: { tabId },
349	      func: injectWebMCPExecutor,
350	      args: [siteConfig.tools.map((t) => ({ name: t.name, handler: t.handler }))],
351	      world: 'MAIN',
352	    });
353	
354	    // 注入桥接脚本用于通信
355	    await chrome.scripting.executeScript({
356	      target: { tabId },
357	      func: injectWebMCPBridge,
358	      world: 'ISOLATED',
359	    });
360	
361	    registeredSiteTools.set(tabId, siteConfig);
362	    console.log(`[WebMCP] 已为标签页 ${tabId} 注册 ${siteConfig.tools.length} 个工具`);
363	  } catch (error) {
364	    console.error(`[WebMCP] 注册工具失败:`, error);
365	  }
366	}
367	
368	/**
369	 * 注入到 MAIN world 的执行器
370	 * 使用 lazy eval + 缓存：只存储 handler 字符串，首次调用时编译并缓存
371	 * 这样既安全（避免 IIFE 在页面加载时执行），又高效（后续调用复用编译结果）
372	 */
373	function injectWebMCPExecutor(tools: Array<{ name: string; handler: string }>) {
374	  // 防止重复注入
375	  if ((window as any).__WEBMCP_EXECUTOR_LOADED__) return;
376	  (window as any).__WEBMCP_EXECUTOR_LOADED__ = true;
377	
378	  // 存储工具 handler 字符串（不立即 eval）
379	  const toolHandlers = new Map<string, string>();
380	  // 缓存编译后的函数
381	  const compiledCache = new Map<string, (...args: unknown[]) => unknown>();
382	
383	  // 只存储 handler 字符串，不编译
384	  tools.forEach((tool) => {
385	    toolHandlers.set(tool.name, tool.handler);
386	    console.log(`[WebMCP] 注册工具: ${tool.name}`);
387	  });
388	
389	  // 监听工具执行请求 (通过 postMessage 从 ISOLATED world)
390	  // 注意：不能使用 async/await，因为 esbuild 会转换成 __async helper，在 MAIN world 中不存在
391	  window.addEventListener('message', (event) => {
392	    if (event.source !== window || event.data?.type !== 'webmcp:execute-tool') return;
393	
394	    const { requestId, toolName, params } = event.data;
395	    console.log(`[WebMCP] 执行工具: ${toolName}`, params);
396	
397	    const handlerCode = toolHandlers.get(toolName);
398	    if (!handlerCode) {
399	      window.postMessage(
400	        {
401	          type: 'webmcp:tool-result',
402	          requestId,
403	          result: null,
404	          error: `工具 ${toolName} 未找到`,
405	        },
406	        '*',
407	      );
408	      return;
409	    }
410	
411	    // Lazy eval + 缓存: 首次调用时编译，后续复用
412	    Promise.resolve()
413	      .then(() => {
414	        let handler = compiledCache.get(toolName);
415	        if (!handler) {
416	          console.log(`[WebMCP] 首次编译工具: ${toolName}`);
417	          handler = eval(`(${handlerCode})`) as (...args: unknown[]) => unknown;
418	          compiledCache.set(toolName, handler);
419	        }
420	        return handler(params);
421	      })
422	      .then((result) => {
423	        window.postMessage(
424	          {
425	            type: 'webmcp:tool-result',
426	            requestId,
427	            result,
428	            error: null,
429	          },
430	          '*',
431	        );
432	      })
433	      .catch((error) => {
434	        window.postMessage(
435	          {
436	            type: 'webmcp:tool-result',
437	            requestId,
438	            result: null,
439	            error: error.message || String(error),
440	          },
441	          '*',
442	        );
443	      });
444	  });
445	
446	  console.log('[WebMCP] Executor initialized with', toolHandlers.size, 'tools');
447	}
448	
449	/**
450	 * 注入到 ISOLATED world 的桥接脚本
451	 */
452	function injectWebMCPBridge() {
453	  if ((window as any).__WEBMCP_BRIDGE_LOADED__) return;
454	  (window as any).__WEBMCP_BRIDGE_LOADED__ = true;
455	
456	  const pendingRequests = new Map<string, (response: any) => void>();
457	
458	  // 监听来自 background 的消息
459	  chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
460	    if (request.type === 'webmcp:call-tool') {
461	      const requestId = `req-${Date.now()}-${Math.random()}`;
462	      pendingRequests.set(requestId, sendResponse);
463	
464	      // 通过 postMessage 转发到 MAIN world
465	      window.postMessage(
466	        {
467	          type: 'webmcp:execute-tool',
468	          requestId,
469	          toolName: request.toolName,
470	          params: request.params,
471	        },
472	        '*',
473	      );
474	
475	      return true; // 异步响应
476	    }
477	  });
478	
479	  // 监听来自 MAIN world 的结果 (通过 postMessage)
480	  window.addEventListener('message', (event) => {
481	    if (event.source !== window || event.data?.type !== 'webmcp:tool-result') return;
482	
483	    const { requestId, result, error } = event.data;
484	    const sendResponse = pendingRequests.get(requestId);
485	    if (sendResponse) {
486	      sendResponse({ result, error });
487	      pendingRequests.delete(requestId);
488	    }
489	  });
490	
491	  console.log('[WebMCP] Bridge initialized');
492	}
493	
494	/**
495	 * 获取指定标签页的可用工具
496	 */
497	export function getTabTools(tabId: number): SiteTool[] {
498	  const config = registeredSiteTools.get(tabId);
499	  return config?.tools || [];
500	}
501	
502	/**
503	 * 获取所有已注册的网站工具
504	 */
505	export function getAllRegisteredTools(): Map<number, SiteConfig> {
506	  return registeredSiteTools;
507	}
508	
509	/**
510	 * 等待标签页加载完成
511	 */
512	function waitForTabLoad(tabId: number, timeout = 15000): Promise<void> {
513	  return new Promise((resolve, reject) => {
514	    const timer = setTimeout(() => {
515	      chrome.tabs.onUpdated.removeListener(listener);
516	      reject(new Error('页面加载超时'));
517	    }, timeout);
518	
519	    const listener = (updatedTabId: number, changeInfo: chrome.tabs.TabChangeInfo) => {
520	      if (updatedTabId === tabId && changeInfo.status === 'complete') {
521	        clearTimeout(timer);
522	        chrome.tabs.onUpdated.removeListener(listener);
523	        // 额外等待一点时间让 JS 执行完成
524	        setTimeout(resolve, 500);
525	      }
526	    };
527	
528	    chrome.tabs.onUpdated.addListener(listener);
529	  });
530	}
531	
532	/**
533	 * 执行网站工具 - 直接在页面上执行
534	 * 支持 __navigate__ + __then__ 协议用于需要页面跳转的操作
535	 */
536	export async function executeWebMCPTool(
537	  tabId: number,
538	  toolName: string,
539	  params: Record<string, any>,
540	): Promise<{ result: any; error: string | null }> {
541	  const config = registeredSiteTools.get(tabId);
542	  if (!config) {
543	    return { result: null, error: '该标签页没有注册工具' };
544	  }
545	
546	  const tool = config.tools.find((t) => t.name === toolName);
547	  if (!tool) {
