"""WebMCP API for managing site tool configurations."""

import functools
import json
import re
import tempfile
from pathlib import Path
from typing import List, Optional, Tuple
from urllib.parse import urlparse
from pydantic import BaseModel

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer

from . import database as db
from .analytics import track_match_url

router = APIRouter(prefix="/api/webmcp", tags=["webmcp"])

# Data directory for WebMCP configurations
DATA_DIR = Path(__file__).parent / "data" / "webmcp"
DATA_DIR.mkdir(parents=True, exist_ok=True)

SITE_NAME_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,63}$")
TOOL_NAME_RE = re.compile(r"^[a-z][a-z0-9_]{1,63}$")
DOMAIN_RE = re.compile(r"^(?:[a-z0-9-]+\.)+[a-z]{2,}$")
MAX_TOOLS = 12
MAX_HANDLER_LENGTH = 20000
MAX_URL_PATTERN_LENGTH = 500
MAX_DESCRIPTION_LENGTH = 500
BLOCKED_HANDLER_SNIPPETS = {
    "document.cookie": "Cookie access is not allowed in handlers.",
    "localstorage": "localStorage access is not allowed in handlers.",
    "sessionstorage": "sessionStorage access is not allowed in handlers.",
    "navigator.sendbeacon": "sendBeacon is not allowed in handlers.",
    "xmlhttprequest": "XMLHttpRequest is not allowed in handlers. Use fetch instead.",
    "websocket": "WebSocket is not allowed in handlers.",
    "eventsource": "EventSource is not allowed in handlers.",
    "cookieStore".lower(): "cookieStore access is not allowed in handlers.",
}
BLOCKED_HANDLER_PATTERNS = [
    (re.compile(r"\beval\s*\(", flags=re.IGNORECASE), "eval() is not allowed in handlers."),
    (re.compile(r"\bFunction\s*\("), "Function() is not allowed in handlers."),
    (re.compile(r"\bimport\s*\(", flags=re.IGNORECASE), "Dynamic import is not allowed in handlers."),
]


# Security
security = HTTPBearer()


def verify_api_key(credentials: HTTPAuthorizationCredentials = Depends(security)) -> str:
    """Verify API key and return the username."""
    token = credentials.credentials
    user_id = db.validate_api_key(token)
    if user_id:
        return user_id
    raise HTTPException(status_code=401, detail="Invalid or missing API key")


# Cache for compiled patterns and configs
@functools.lru_cache(maxsize=1)
def _load_all_configs_cached(mtime: float) -> List[Tuple[re.Pattern, dict]]:
    """Load and cache all configs with pre-compiled regex patterns.

    Args:
        mtime: Directory modification time, used as cache invalidation key

    Returns:
        List of (compiled_pattern, config_dict) tuples
    """
    configs = []
    for file_path in DATA_DIR.glob("*.json"):
        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            try:
                compiled = re.compile(data['url_pattern'])
                configs.append((compiled, data))
            except re.error:
                # Skip invalid patterns
                continue
    return configs


def _get_cached_configs() -> List[Tuple[re.Pattern, dict]]:
    """Get cached configs, auto-refresh when directory changes."""
    mtime = DATA_DIR.stat().st_mtime
    return _load_all_configs_cached(mtime)


def invalidate_config_cache():
    """Invalidate the config cache (call after create/update/delete)."""
    _load_all_configs_cached.cache_clear()


# Models - WebMCP 标准格式
class InputSchema(BaseModel):
    """JSON Schema for tool input (WebMCP standard)"""
    type: str = "object"
    properties: dict = {}
    required: Optional[List[str]] = None


class WebMCPTool(BaseModel):
    """WebMCP standard tool format"""
    name: str
    description: str
    inputSchema: InputSchema  # WebMCP 标准格式
    handler: str  # JavaScript code to execute


class SiteConfig(BaseModel):
    url_pattern: str  # Regex pattern string
    site_name: str
    allowed_domains: Optional[List[str]] = None
    tools: List[WebMCPTool]


class SiteListItem(BaseModel):
    site_name: str
    url_pattern: str
    tool_count: int
    tools: List[str]


def _extract_allowed_domains(url_pattern: str) -> List[str]:
    """Extract host suffixes from a URL regex for absolute URL allowlisting."""
    normalized = url_pattern.replace(r"\.", ".")
    matches = re.findall(r"(?:[a-z0-9-]+\.)+[a-z]{2,}", normalized, flags=re.IGNORECASE)
    domains = {
        match.lower().removeprefix("www.")
        for match in matches
    }
    for group, suffix in re.findall(r"\(([a-z0-9-|]+)\)\.([a-z.]{2,})", normalized, flags=re.IGNORECASE):
        for label in group.split("|"):
            label = label.strip().lower()
            if re.fullmatch(r"[a-z0-9-]+", label):
                domains.add(f"{label}.{suffix.lower()}".removeprefix("www."))
    return sorted(domains)


def _validate_handler_domains(handler: str, allowed_domains: List[str]) -> None:
    """Reject absolute URLs that target domains outside the site's allowed suffixes."""
    for url in re.findall(r"https?://[^\s\"'`]+", handler):
        sanitized = url.split("${", 1)[0].rstrip(");,")
        host = (urlparse(sanitized).hostname or "").lower()
        if not host:
            continue
        if any(host == domain or host.endswith(f".{domain}") for domain in allowed_domains):
            continue
        raise HTTPException(
            status_code=400,
            detail=f"Handler references external domain '{host}', which is outside the site URL pattern allowlist.",
        )


def validate_site_config(config: SiteConfig) -> None:
    """Validate WebMCP site config beyond basic schema parsing."""
    if not SITE_NAME_RE.fullmatch(config.site_name):
        raise HTTPException(
            status_code=400,
            detail="Invalid site_name. Use lowercase letters, numbers, hyphens, and underscores only.",
        )

    if len(config.url_pattern) > MAX_URL_PATTERN_LENGTH:
        raise HTTPException(status_code=400, detail="url_pattern is too long.")
    if not config.url_pattern.startswith("^https?://"):
        raise HTTPException(status_code=400, detail="url_pattern must start with ^https?://")

    try:
        re.compile(config.url_pattern)
    except re.error as exc:
        raise HTTPException(status_code=400, detail=f"Invalid url_pattern regex: {exc}") from exc

    allowed_domains = _extract_allowed_domains(config.url_pattern)
    for domain in config.allowed_domains or []:
        normalized = domain.strip().lower().removeprefix("www.")
        if not DOMAIN_RE.fullmatch(normalized):
            raise HTTPException(
                status_code=400,
                detail=f"Invalid allowed domain '{domain}'.",
            )
        if normalized and normalized not in allowed_domains:
            allowed_domains.append(normalized)
    if not allowed_domains:
        raise HTTPException(
            status_code=400,
            detail="url_pattern must include at least one concrete domain suffix.",
        )

    if not config.tools:
        raise HTTPException(status_code=400, detail="At least one tool is required.")
    if len(config.tools) > MAX_TOOLS:
        raise HTTPException(status_code=400, detail=f"Too many tools. Maximum is {MAX_TOOLS}.")

    seen_names = set()
    for tool in config.tools:
        if not TOOL_NAME_RE.fullmatch(tool.name):
            raise HTTPException(
                status_code=400,
                detail=f"Invalid tool name '{tool.name}'. Use lowercase snake_case.",
            )
        if tool.name in seen_names:
            raise HTTPException(status_code=400, detail=f"Duplicate tool name '{tool.name}'.")
        seen_names.add(tool.name)

        if not tool.description or len(tool.description) > MAX_DESCRIPTION_LENGTH:
            raise HTTPException(
                status_code=400,
                detail=f"Tool '{tool.name}' must have a non-empty description under {MAX_DESCRIPTION_LENGTH} characters.",
            )

        if tool.inputSchema.type != "object":
            raise HTTPException(
                status_code=400,
                detail=f"Tool '{tool.name}' inputSchema.type must be 'object'.",
            )

        properties = tool.inputSchema.properties or {}
        if not isinstance(properties, dict):
            raise HTTPException(
                status_code=400,
                detail=f"Tool '{tool.name}' inputSchema.properties must be an object.",
            )

        required = tool.inputSchema.required or []
        missing_required = [field for field in required if field not in properties]
        if missing_required:
            raise HTTPException(
                status_code=400,
                detail=f"Tool '{tool.name}' required fields must exist in properties: {', '.join(missing_required)}.",
            )

        if not tool.handler or len(tool.handler) > MAX_HANDLER_LENGTH:
            raise HTTPException(
                status_code=400,
                detail=f"Tool '{tool.name}' handler must be present and shorter than {MAX_HANDLER_LENGTH} characters.",
            )

        handler_lower = tool.handler.lower()
        for snippet, message in BLOCKED_HANDLER_SNIPPETS.items():
            if snippet in handler_lower:
                raise HTTPException(
                    status_code=400,
                    detail=f"Tool '{tool.name}' rejected: {message}",
                )

        for pattern, message in BLOCKED_HANDLER_PATTERNS:
            if pattern.search(tool.handler):
                raise HTTPException(
                    status_code=400,
                    detail=f"Tool '{tool.name}' rejected: {message}",
                )

        _validate_handler_domains(tool.handler, allowed_domains)


# Helper functions
def load_site_config(site_name: str) -> Optional[SiteConfig]:
    """Load a site configuration from file."""
    file_path = DATA_DIR / f"{site_name}.json"
    if not file_path.exists():
        return None

    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    return SiteConfig(**data)


def save_site_config(config: SiteConfig, allow_overwrite: bool = True) -> None:
    """Save a site configuration to file."""
    validate_site_config(config)
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    file_path = DATA_DIR / f"{config.site_name}.json"
    if file_path.exists() and not allow_overwrite:
        raise HTTPException(status_code=409, detail=f"Site '{config.site_name}' already exists")

    with tempfile.NamedTemporaryFile(
        "w",
        encoding="utf-8",
        dir=DATA_DIR,
        prefix=f"{config.site_name}.",
        suffix=".tmp",
        delete=False,
    ) as tmp:
        json.dump(config.model_dump(), tmp, indent=2, ensure_ascii=False)
        tmp.write("\n")
        tmp_path = Path(tmp.name)

    tmp_path.replace(file_path)
    invalidate_config_cache()


def list_all_sites() -> List[SiteConfig]:
    """List all site configurations."""
    cached = _get_cached_configs()
    return [SiteConfig(**data) for _, data in cached]


def match_url_to_site(url: str) -> Optional[SiteConfig]:
    """Match a URL to a site configuration using cached compiled patterns."""
    for compiled_pattern, data in _get_cached_configs():
        if compiled_pattern.match(url):
            return SiteConfig(**data)
    return None


# API Endpoints
@router.get("/sites", response_model=List[SiteListItem])
async def get_sites():
    """List all configured sites with their tools."""
    configs = list_all_sites()
    return [
        SiteListItem(
            site_name=c.site_name,
            url_pattern=c.url_pattern,
            tool_count=len(c.tools),
            tools=[t.name for t in c.tools],
        )
        for c in configs
    ]


@router.get("/sites/{site_name}", response_model=SiteConfig)
async def get_site(site_name: str):
    """Get tool configuration for a specific site."""
    config = load_site_config(site_name)
    if not config:
        raise HTTPException(status_code=404, detail=f"Site '{site_name}' not found")
    return config


@router.get("/match", response_model=Optional[SiteConfig])
async def match_site(url: str = Query(..., description="URL to match against site patterns")):
    """Match a URL to a site and return its tool configuration."""
    # Track URL for analytics
    track_match_url(url)

    config = match_url_to_site(url)
    if not config:
        return None
    return config


@router.post("/sites", response_model=SiteConfig)
async def create_site(config: SiteConfig, username: str = Depends(verify_api_key)):
    """Create a site configuration."""
    save_site_config(config, allow_overwrite=False)
    return config


@router.put("/sites/{site_name}", response_model=SiteConfig)
async def update_site(site_name: str, config: SiteConfig, username: str = Depends(verify_api_key)):
    """Update an existing site configuration."""
    if site_name != config.site_name:
        raise HTTPException(status_code=400, detail="Path site_name must match config.site_name")
    file_path = DATA_DIR / f"{site_name}.json"
    if not file_path.exists():
        raise HTTPException(status_code=404, detail=f"Site '{site_name}' not found")
    save_site_config(config, allow_overwrite=True)
    return config


@router.delete("/sites/{site_name}")
async def delete_site(site_name: str, username: str = Depends(verify_api_key)):
    """Delete a site configuration."""
    file_path = DATA_DIR / f"{site_name}.json"
    if not file_path.exists():
        raise HTTPException(status_code=404, detail=f"Site '{site_name}' not found")
    file_path.unlink()
    invalidate_config_cache()
    return {"message": f"Site '{site_name}' deleted"}


# Bulk operations
@router.get("/export", response_model=List[SiteConfig])
