def get_analytics_summary(days: Optional[int] = None) -> dict:
    """Get analytics summary for lifetime (default) or the last N days."""
    cutoff_str = None
    if days is not None:
        cutoff = datetime.now() - timedelta(days=days)
        cutoff_str = cutoff.strftime("%Y-%m-%d")

    def in_window(date: str) -> bool:
        return cutoff_str is None or date >= cutoff_str

    with _analytics_lock:
        # Calculate totals
        total_api = 0
        total_agent = 0
        total_human = 0
        endpoint_stats = {}
        daily_stats = defaultdict(lambda: {"total": 0, "agent": 0, "human": 0})

        for endpoint, dates in _analytics_data["api_calls"].items():
            endpoint_total = 0
            endpoint_agent = 0
            endpoint_human = 0

            for date, count in dates.items():
                if in_window(date):
                    endpoint_total += count
                    total_api += count
                    daily_stats[date]["total"] += count

            # Get agent/human breakdown for this endpoint
            for date, count in _analytics_data["agent_calls"].get(endpoint, {}).items():
                if in_window(date):
                    endpoint_agent += count
                    total_agent += count
                    daily_stats[date]["agent"] += count

            for date, count in _analytics_data["human_calls"].get(endpoint, {}).items():
                if in_window(date):
                    endpoint_human += count
                    total_human += count
                    daily_stats[date]["human"] += count

            if endpoint_total > 0:
                endpoint_stats[endpoint] = {
                    "total": endpoint_total,
                    "agent": endpoint_agent,
                    "human": endpoint_human,
                    "agent_pct": round(endpoint_agent / endpoint_total * 100, 1) if endpoint_total > 0 else 0,
                }

        # Sort endpoints by total calls
        endpoint_stats = dict(sorted(endpoint_stats.items(), key=lambda x: x[1]["total"], reverse=True))

        # Get top user agents
        top_agents = sorted(_analytics_data["user_agents"].items(), key=lambda x: x[1], reverse=True)[:10]

        # Calculate IP stats
        all_ips = set()
        daily_unique_ips = {}
        for date, ips in _analytics_data["daily_ips"].items():
            if in_window(date):
                all_ips.update(ips)
                daily_unique_ips[date] = len(ips)

        # Get top IPs by request count
        top_ips = sorted(
            [(ip, count) for ip, count in _analytics_data["ip_requests"].items()],
            key=lambda x: x[1],
            reverse=True
        )[:20]

        # Calculate match_urls stats (top URLs in period)
        match_url_totals = {}
        for url_key, dates in _analytics_data["match_urls"].items():
            total = sum(count for date, count in dates.items() if in_window(date))
            if total > 0:
                match_url_totals[url_key] = total
        top_match_urls = sorted(match_url_totals.items(), key=lambda x: x[1], reverse=True)[:50]

        return {

